import fs from 'node:fs/promises';
import path from 'node:path';
import type { Response } from 'express';
import { config } from '../../config.js';
import { contentDisposition, type Storage } from './index.js';

/** Development driver: files under LOCAL_UPLOAD_DIR, never exposed as static files. */
export class LocalStorage implements Storage {
  private resolve(key: string) {
    const full = path.resolve(config.uploadDir, key);
    // Keys are generated by us, but guard against traversal anyway.
    if (!full.startsWith(config.uploadDir + path.sep)) throw new Error('Invalid storage key');
    return full;
  }

  async put(key: string, sourcePath: string) {
    const dest = this.resolve(key);
    await fs.mkdir(path.dirname(dest), { recursive: true });
    await fs.copyFile(sourcePath, dest);
  }

  async send(res: Response, key: string, opts: { contentType: string; downloadName?: string; inline?: boolean; cacheSeconds?: number }) {
    const file = this.resolve(key);
    res.setHeader('Content-Type', opts.contentType);
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('Cache-Control', opts.cacheSeconds ? `private, max-age=${opts.cacheSeconds}` : 'private, no-store');
    if (opts.downloadName) res.setHeader('Content-Disposition', contentDisposition(opts.downloadName, opts.inline ?? true));
    // sendFile supports HTTP Range requests, so videos can seek.
    await new Promise<void>((resolve, reject) =>
      res.sendFile(file, { headers: {}, acceptRanges: true, cacheControl: false, lastModified: true }, (err) => (err ? reject(err) : resolve())),
    ).catch((err: any) => {
      if (err?.code === 'ENOENT' && !res.headersSent) res.status(404).json({ error: { code: 'not_found', message: 'File missing from storage' } });
      else if (!res.headersSent) throw err;
    });
  }

  async remove(key: string) {
    await fs.rm(this.resolve(key), { force: true });
  }
}
